/* The nineteen names those fourteen profiles answer to, and the space each one
   builds.  An extended-range name takes the same profile bytes as its base --
   the profile carries no range, and the two spaces are reported unequal
   because the flag below is what differs -- so it is the name and the flag that
   are per-space rather than the profile.

   Every one of the nineteen is an immortal singleton: two calls answer the same
   pointer at the immortal retain count, exactly as the device names do.  So
   each row is built on first use and then kept. */
enum { CGColorSpaceNamedRGBV4Count = 19 };

static const struct {
    const char *name;
    const struct cgs_rgb_v4 *profile;
    bool extended;
} CGColorSpaceNamedRGBV4[CGColorSpaceNamedRGBV4Count] = {
    { "kCGColorSpaceDisplayP3", &DisplayP3, false },
    { "kCGColorSpaceExtendedDisplayP3", &DisplayP3, true },
    { "kCGColorSpaceITUR_709", &ITUR_709, false },
    { "kCGColorSpaceITUR_2020", &ITUR_2020, false },
    { "kCGColorSpaceExtendedITUR_2020", &ITUR_2020, true },
    { "kCGColorSpaceITUR_2020_sRGBGamma", &ITUR_2020_sRGBGamma, false },
    { "kCGColorSpaceDisplayP3_709OETF", &DisplayP3_709OETF, false },
    { "kCGColorSpaceROMMRGB", &ROMMRGB, false },
    { "kCGColorSpaceDCIP3", &DCIP3, false },
    { "kCGColorSpaceACESCGLinear", &ACESCGLinear, false },
    { "kCGColorSpaceCoreMedia709", &CoreMedia709, false },
    { "kCGColorSpaceGenericRGB", &GenericRGB, false },
    { "kCGColorSpaceGenericRGBLinear", &GenericRGBLinear, false },
    { "kCGColorSpaceLinearSRGB", &LinearSRGB, false },
    { "kCGColorSpaceExtendedLinearSRGB", &LinearSRGB, true },
    { "kCGColorSpaceLinearDisplayP3", &LinearDisplayP3, false },
    { "kCGColorSpaceExtendedLinearDisplayP3", &LinearDisplayP3, true },
    { "kCGColorSpaceLinearITUR_2020", &LinearITUR_2020, false },
    { "kCGColorSpaceExtendedLinearITUR_2020", &LinearITUR_2020, true }
};

static struct CGColorSpace *CGColorSpaceNamedRGBV4State[CGColorSpaceNamedRGBV4Count];

/* Build, or find, the space one of the nineteen names on this template
   resolves to.  Answers NULL for every other name, so the caller can hand it
   the name it failed to recognise and get the same answer back. */
static CGColorSpaceRef CGColorSpaceCreateNamedRGBV4(CFStringRef name)
{
    struct CGColorSpace *s;
    unsigned char *profile;
    size_t len;
    int i;

    for (i = 0; i < CGColorSpaceNamedRGBV4Count; i++) {
        if (!CGColorSpaceNameEqualsASCII(name, CGColorSpaceNamedRGBV4[i].name))
            continue;
        if (CGColorSpaceNamedRGBV4State[i])
            return CGColorSpaceNamedRGBV4State[i];
        profile = put_rgb_v4(CGColorSpaceNamedRGBV4[i].profile, &len);
        if (!profile)
            return NULL;
        s = calloc(1, sizeof *s);
        if (!s) {
            free(profile);
            return NULL;
        }
        s->immortal = true;
        s->model = kCGColorSpaceModelRGB;
        s->type = CGColorSpaceTypeICC;
        s->ncomp = 3;
        /* A literal like the device names', and not owned. */
        s->name = CGColorSpaceNamedRGBV4[i].name;
        s->extended = CGColorSpaceNamedRGBV4[i].extended;
        s->profile = profile;
        s->profileLen = len;
        CGColorSpaceNamedRGBV4State[i] = s;
        return s;
    }
    return NULL;
}

/* The v2 monochrome/TRC template, holding three profiles.

   All three gray spaces are gray profiles rather than RGB ones, and v2 rather
   than v4, so they share almost nothing with the eleven above but the header:
   four or five tags rather than ten or eleven, the description and copyright
   as the legacy 'desc' and 'text' types rather than 'mluc' records, no
   colorants at all, and one tone curve rather than three.  What they share
   with each other is the shape and the header illuminant; what they share with
   the RGB profiles is the white point, and only exactly -- the quantisation
   step those mostly lose a unit to is not lost by these.

   The tag order is description, constant tag, copyright, white point, tone
   curve, and it is the same as the v4 template's for as far as the two run:
   'desc', 'cprt', 'wtpt'.  The constant tag is there only when a row carries
   one, and 'dscm' goes straight after the description as it does on that
   template.  The tone curve is a parameter -- the identity of LinearGray, the
   461/256 gamma GenericRGB shares with GenericGray -- except where a row
   supplies a sampled table of its own, which is how the gamma 2.2 profile
   stores the 1,024 entries Apple quantised sRGB's transfer function to.

   The blocks are laid out the same way as on the v4 template, each aligned and
   the next beginning after it, so for LinearGray -- the one profile here with
   no constant tag, and the one the offsets below are worked out for -- the
   data starts at 132 plus four entries and the two strings run into each
   other's padding: the description ends at 282, the copyright is written at
   284 and ends at 319, and the white point follows at 320.  That leaves the
   tone curve's fourteen bytes finishing at 354, and the profile is the 356
   bytes that pads that to a four-byte boundary.  GenericGray inserts its 1,622
   byte 'dscm' between the description and the copyright and so lands at 2,020
   bytes, and the gamma 2.2 profile does the same with a 2,074 byte one and a
   2,060 byte curve and lands at 4,508. */

/* One gray space's parameters.  As with the RGB rows above, these are
   constants recovered from the profile the name resolves to rather than
   anything worked out at run time. */
struct cgs_gray_v2 {
    const char *desc;
    const char *cprt;
    int created[6];
    int32_t wtpt[3];
    struct cgs_icc_curve trc;
    /* The tone curve as a sampled table instead, for the one row here whose
       profile stores 1,024 entries rather than a parameter.  When this is null
       'trc' is written as it is elsewhere; when it is not, 'trc' is ignored. */
    const uint16_t *trcTable;
    int trcCount;
    /* The profile version, as the four-byte header field.  All three predate
       the 'mluc' string types, which is why they carry legacy strings here as
       well; the linear gray profile is v2.1, the generic one v2.2, and the
       gamma one v2.0. */
    int32_t version;
    /* The manufacturer, spelled the way this row writes it; the three differ,
       two writing 'none' and one naming itself. */
    const char *manufacturer;
    /* Whether the 'desc' carries a ScriptCode copy of its ASCII; see
       put_desc.  Only the generic gray profile does. */
    int descScriptCode;
    /* Whether the description carries the terminator byte that follows its
       67-byte field.  The linear and gamma profiles do and the generic one
       does not; nothing in the format requires either, so the row says. */
    int descTrailer;
    /* A constant tag, which for these rows means only the 'dscm' translation
       list, and where in the table it belongs. */
    const unsigned char *extraData[CGICCRGBV4MaxExtraTags];
    const char *extraName[CGICCRGBV4MaxExtraTags];
    const struct cgs_mluc_record *extraRecords[CGICCRGBV4MaxExtraTags];
    int extraRecordCount[CGICCRGBV4MaxExtraTags];
    int32_t extraLen[CGICCRGBV4MaxExtraTags];
    int extraCount;
    int extrasWhere;
};

/* One of this row's constant tags, which for the gray template is only ever
   the same shape of thing the RGB rows carry: see put_extra_tag. */
static size_t put_gray_v2_extra(unsigned char *p, const struct cgs_gray_v2 *v,
    int i)
{
    return put_extra_tag(p, v->extraData, v->extraRecords, v->extraLen,
        v->extraRecordCount, i);
}

/* Assemble the profile.  Four blocks always go out -- the two strings, the
   white point and the single tone curve -- plus whatever constant tag the row
   carries, and the tags are pointed at them.  The generic gray profile's one
   constant tag is the 'dscm' translation list and comes second, straight after
   the description, which is where the RGB template's goes too. */
static unsigned char *put_gray_v2(const struct cgs_gray_v2 *v, size_t *outLen)
{
    enum { desc, cprt, wtpt, curve, blockCount };
    static const char *const fixed[blockCount] = {
        "desc", "cprt", "wtpt", "kTRC"
    };
    unsigned char *p;
    size_t dlen, tlen, len;
    const char *name[blockCount + CGICCRGBV4MaxExtraTags];
    int32_t blockLen[blockCount + CGICCRGBV4MaxExtraTags];
    int32_t blockOff[blockCount + CGICCRGBV4MaxExtraTags];
    int n, i, k;

    /* put_desc and put_text both size themselves from the string, so the two
       lengths are worked out here rather than written down.

       The description ends with the ScriptCode field and then a terminator, and
       the three profiles on this template disagree about whether that last byte
       is there: two carry it and one does not, which is why the field is a
       row's to say rather than a constant.  Nothing about the format requires
       either.  The RGB template does not need the choice, since the three
       profiles on it that carry legacy strings all have it. */
    dlen = 12 + (strlen(v->desc) + 1) + 4 + 4 + 2
        + (v->descScriptCode ? 1 : 0) + 67 + v->descTrailer;
    /* A sampled curve is a signature, four reserved bytes, a count and two
       bytes per entry; a parameter is the fourteen bytes put_icc_curve writes
       or, for a 'para', the twelve plus four per word that it writes. */
    if (v->trcTable)
        tlen = 12 + 2 * (size_t)v->trcCount;
    else
        tlen = v->trc.parametric ? 12 + 4 * (size_t)v->trc.words : 14;

    /* The tag table lists the description, then this row's constant tags if it
       has any, then the rest.  After the description is the one placement the
       gray template sees -- the two rows with an extra put 'dscm' there -- and
       the RGB template's own enum is reused for it rather than duplicated,
       since the two mean the same thing. */
    n = 0;
    name[n++] = fixed[0];
    if (v->extrasWhere == CGICCRGBV4ExtrasAfterDesc) {
        for (k = 0; k < v->extraCount; k++)
            name[n++] = v->extraName[k];
    }
    for (i = 1; i < blockCount; i++)
        name[n++] = fixed[i];

    /* As in put_rgb_v4, the offsets are assigned in one pass and used again
       below, so the two cannot disagree about where a block went.  The blocks
       are laid out in the order the table lists them. */
    len = CGICCTagTableOffset + (size_t)n * CGICCTagEntrySize;
    k = 0;
    for (i = 0; i < n; i++) {
        int32_t l;

        if (i == 0)
            l = (int32_t)dlen;
        else if (i < 1 + (v->extrasWhere == CGICCRGBV4ExtrasAfterDesc
                     ? v->extraCount : 0))
            l = (int32_t)put_gray_v2_extra(NULL, v, k++);
        else if (name[i] == fixed[1])
            l = (int32_t)(8 + strlen(v->cprt) + 1);
        else if (name[i] == fixed[2])
            l = CGICCXYZLength;
        else
            l = (int32_t)tlen;
        blockLen[i] = l;
        blockOff[i] = (int32_t)icc_pad(len);
        len = icc_pad(len) + (size_t)l;
    }
    /* The tone curve is fourteen bytes and leaves the profile two short of a
       boundary in the linear case, so the size counts the padding rather than
       the last tag. */
    len = icc_pad(len);

    p = calloc(1, len);
    if (!p)
        return NULL;

    put_icc_header(p, len, v->created, v->version, "GRAY", v->manufacturer);
    put_be32(p + CGICCTagCountOffset, (uint32_t)n);
    for (i = 0; i < n; i++) {
        unsigned char *e = p + CGICCTagTableOffset + i * CGICCTagEntrySize;

        memcpy(e, name[i], 4);
        put_be32(e + 4, (uint32_t)blockOff[i]);
        put_be32(e + 8, (uint32_t)blockLen[i]);
    }

    /* The blocks in table order.  The generic gray profile's description takes
       the ScriptCode form and the linear one takes the empty form, and each
       row says which is its own. */
    k = 0;
    for (i = 0; i < n; i++) {
        unsigned char *e = p + blockOff[i];

        if (i == 0)
            put_desc(e, v->desc, v->descScriptCode, dlen);
        else if (i < 1 + (v->extrasWhere == CGICCRGBV4ExtrasAfterDesc
                      ? v->extraCount : 0))
            put_gray_v2_extra(e, v, k++);
        else if (name[i] == fixed[1])
            put_text(e, v->cprt);
        else if (name[i] == fixed[2])
            put_xyz_i32(e, v->wtpt);
        else if (v->trcTable)
            put_curve_sampled(e, v->trcTable, (size_t)v->trcCount);
        else
            put_icc_curve(e, &v->trc);
    }

    *outLen = len;
    return p;
}

/* The one profile, which the two linear names below share.  Recovered from the
   space kCGColorSpaceLinearGray resolves to; put_gray_v2 was checked against it
   by rebuilding the profile and comparing it byte for byte. */
static const struct cgs_gray_v2 LinearGray = {
    .desc = "Linear Gray",
    .version = CGICCVersionV21,
    .manufacturer = "APPL",
    .descTrailer = 1,
    .created = { 2016, 1, 1, 0, 0, 0 },
    .cprt = "Copyright Apple Inc., 2016",
    /* The D50 illuminant, quantised exactly -- unlike seven of the eight
       non-linear RGB spaces, whose white point lands a unit below it. */
    .wtpt = { 0xf6d6, 0x10000, 0xd32d },
    .trc = { 0, 0, 256, 0, { 0x0 } },  /* u8Fixed8 gamma of 1.0 */
};

