/* kCGColorSpaceGenericGrayGamma2_2's profile, the third on this template, and
   the one kCGColorSpaceExtendedGray points at as well -- the two are the same
   bytes and differ only in the flag CGColorSpaceCreateWithName sets, the way
   the extended RGB names do.  Recovered from the space the first name resolves
   to and checked byte for byte by rebuilding it.

   It writes 'none' where the linear one names Apple, and its description is
   the plain ASCII with neither a ScriptCode copy nor a gap for one -- yet it
   is the one that keeps the trailing terminator byte the generic gray profile
   leaves out.  Its white point is the generic gray profile's, unit for unit.
   What makes it its own profile is the tone curve: not the u8Fixed8 gamma of
   its siblings but the 1,024 entries above. */
static const struct cgs_gray_v2 GenericGrayGamma22 = {
    .desc = "Generic Gray Gamma 2.2 Profile",
    .version = CGICCVersionV20,
    .manufacturer = "none",
    .descTrailer = 1,
    .created = { 2012, 8, 23, 15, 46, 15 },
    .cprt = "Copyright Apple Inc., 2012",
    .wtpt = { 0xf351, 0x10000, 0x116cc },
    .trcTable = cgsGrayGamma22Tone,
    .trcCount = 1024,
    .extraName = { "dscm" },
    .extraRecords = { GenericGrayGamma22Dscm },
    .extraRecordCount = { 31 },
    .extraCount = 1,
    .extrasWhere = CGICCRGBV4ExtrasAfterDesc,
};

/* The five names, and the extended flag each carries.

   kCGColorSpaceExtendedLinearGray takes the very same 356 bytes as the space
   it is named after, and kCGColorSpaceExtendedGray the very same 4,508 as
   kCGColorSpaceGenericGrayGamma2_2: neither profile records a range, so the
   profile cannot be what tells the pair apart.  Each pair is reported unequal
   and is the same space once the range is ignored, which is the same
   arrangement the extended RGB names use.  kCGColorSpaceGenericGray has no
   extended counterpart, and builds its own profile. */
enum { CGColorSpaceNamedGrayV2Count = 5 };

static const struct {
    const char *name;
    const struct cgs_gray_v2 *profile;
    bool extended;
} CGColorSpaceNamedGrayV2[CGColorSpaceNamedGrayV2Count] = {
    { "kCGColorSpaceLinearGray", &LinearGray, false },
    { "kCGColorSpaceExtendedLinearGray", &LinearGray, true },
    { "kCGColorSpaceGenericGray", &GenericGray, false },
    { "kCGColorSpaceGenericGrayGamma2_2", &GenericGrayGamma22, false },
    { "kCGColorSpaceExtendedGray", &GenericGrayGamma22, true }
};

static struct CGColorSpace *CGColorSpaceNamedGrayV2State[CGColorSpaceNamedGrayV2Count];

/* Build, or find, the space one of the five gray names resolves to.  Answers
   NULL for every other name, so the caller can fall through to the RGB
   template the same way it falls through from there. */
static CGColorSpaceRef CGColorSpaceCreateNamedGrayV2(CFStringRef name)
{
    struct CGColorSpace *s;
    unsigned char *profile;
    size_t len;
    int i;

    for (i = 0; i < CGColorSpaceNamedGrayV2Count; i++) {
        if (!CGColorSpaceNameEqualsASCII(name, CGColorSpaceNamedGrayV2[i].name))
            continue;
        if (CGColorSpaceNamedGrayV2State[i])
            return CGColorSpaceNamedGrayV2State[i];
        profile = put_gray_v2(CGColorSpaceNamedGrayV2[i].profile, &len);
        if (!profile)
            return NULL;
        s = calloc(1, sizeof *s);
        if (!s) {
            free(profile);
            return NULL;
        }
        s->immortal = true;
        s->model = kCGColorSpaceModelMonochrome;
        s->type = CGColorSpaceTypeICC;
        s->ncomp = 1;
        /* A literal like the device names', and not owned. */
        s->name = CGColorSpaceNamedGrayV2[i].name;
        s->extended = CGColorSpaceNamedGrayV2[i].extended;
        s->profile = profile;
        s->profileLen = len;
        CGColorSpaceNamedGrayV2State[i] = s;
        return s;
    }
    return NULL;
}

/* The three names Apple resolves last, on a second v2 shape of their own.

   kCGColorSpaceSRGB and kCGColorSpaceAdobeRGB1998 -- and the extended-range
   alias of the first, kCGColorSpaceExtendedSRGB, which takes the same profile
   bytes and differs only in the name and the range flag -- are the three
   names this step used to refuse.  Neither resolves like the spaces above:
   each is a classic v2.1 'mntr' profile, the form the identifier table has
   carried all along, and both spell their strings in the legacy types, which
   is what makes them a different shape from the v4 RGB template even though
   they are RGB spaces too.  Everything below was recovered from the profile
   each name resolves to, and put_v2_profile was checked against both by
   rebuilding each and comparing it byte for byte.

   Several things about the two make the template different from the others on
   this list.  The headers are stored rather than composed, because a real
   profile carries dates and attributes nothing here builds should invent, and
   because the two headers differ in the fields a composed one would spend
   effort on: the sRGB profile is a 'Lino' space created by Hewlett-Packard
   and Microsoft with the MSFT/HP renderer fields stamped as the standard
   mandates, while Adobe's is an 'ADBE' space Apple has filed under APPL.  Each
   header's only live field is its size, which the emitter writes over the
   stored byte.

   The sRGB profile's tag table is the longest in the set -- seventeen tags,
   with the 'view', 'lumi', 'meas' and 'tech' blocks of the display-industry
   profile that the others do not carry, and with three 'desc' blocks holding
   the IEC spelling of the space and its preferred viewing conditions.  Most
   of the seventeen tags are stored whole, but not the interesting three: the
   red, green and blue tone curves are ONE shared sampled curve, the 1,024
   entries of which are the very table cgsGrayGamma22Tone already holds.  The
   sRGB transfer function, quantised the same way, is the gamma 2.2 one; the
   row above is reused rather than transcribed, and the emitter places a block
   once for however many tags point at it, which is why the three curve tags
   share the block without moving it.  The six remaining blocks are the
   quantised 'XYZ ' words of the white point, the black point, the three
   colorants and the luminance of the preferred profile, spelled below exactly
   as the profile carries them.

   Adobe's is the smaller profile and is entirely derived: the copyright and
   description as 'text' and 'desc', the black and white points and the three
   colorants as quantised 'XYZ ' words, and the three gamma 2.2 curves as what
   put_icc_curve writes -- 0x233, the u8Fixed8 spelling of 2.199, which is the
   value that makes the space 2.2's.  Nothing in it is stored, and the block
   table is the only place its ten tags get their bytes. */

